   [215]={next_id=216, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="殿下真正的想法我是不知道啦，但是这段时间皇女殿下推掉了很多本应出席的活动和政务，一直在房间里对着迷雾作战地图写写画画。", msg_color="", msg_size=0, talker="白蔷薇", audio="", img="arts/ui/bg/story/storybg_ACT209_103.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4528", 0, 0, 44.5, 204}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
